#include <bits/stdc++.h>
using namespace std;
using LL = long long;
const int MOD = 1e9 + 7;

int modInverse(int a, int m) {
    int m0 = m, t, q;
    int x0 = 0, x1 = 1;
    if (m == 1) return 0;
    while (a > 1) {
        q = a / m;
        t = m;
        m = a % m, a = t;
        t = x0;
        x0 = x1 - q * x0;
        x1 = t;
    }
    if (x1 < 0) x1 += m0;
    return x1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> p(n);
    for (auto &row : p) {
        row.resize(n);
        for (int &val : row) {
            cin >> val;
            val = (LL)val * modInverse(100, MOD) % MOD;
        }
    }

    vector<vector<int>> size_groups(n + 1);
    vector<vector<int>> subset_list(n + 1);
    for (int sz = 0; sz <= n; ++sz) {
        size_groups[sz].resize(1 << n);
        for (int s = 0; s < (1 << n); ++s) {
            if (__builtin_popcount(s) == sz) {
                size_groups[sz][s] = subset_list[sz].size();
                subset_list[sz].push_back(s);
            }
        }
    }

    vector<map<LL, int>> dp(n + 1);
    dp[0][1] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int s = 0; s < (1 << n); ++s) {
            int prod = 1;
            for (int j = 0; j < n; ++j) {
                if (s & (1 << j))
                    prod = (LL)prod * p[i - 1][j] % MOD;
                else
                    prod = (LL)prod * (1 + MOD - p[i - 1][j]) % MOD;
            }
            for (auto &[f, count] : dp[i - 1]) {
                LL mask = 0;
                for (int t : subset_list[i]) {
                    for (int j = 0; j < n; ++j) {
                        if ((t >> j & 1) && (s >> j & 1) && (f >> size_groups[i - 1][t ^ 1 << j] & 1))
                            { mask |= 1LL << size_groups[i][t]; break; }
                    }
                }
                dp[i][mask] = (dp[i][mask] + LL(count) * prod) % MOD;
            }
        }
    }
    cout << dp[n][1] << "\n";
    return 0;
}
